    65	 * snapshot is a display-only reload fallback; a fresh tool result always wins.
    66	 * Hidden result metadata is deliberately excluded.
    67	 */
    68	export function persistOpenAiViewSnapshot<T>(
    69		globals: unknown,
    70		data: T | null,
    71	): boolean {
    72		if (!isStructuredObject(globals)) return false;
    73		const setWidgetState = globals.setWidgetState;
    74		if (typeof setWidgetState !== "function") return false;
    75	
    76		const widgetState = isStructuredObject(globals.widgetState)
    77			? globals.widgetState
    78			: {};
    79		const privateContent = isStructuredObject(widgetState.privateContent)
    80			? widgetState.privateContent
    81			: {};
    82		const nextWidgetState = {
    83			...widgetState,
    84			privateContent: {
    85				...privateContent,
    86				[LOBU_VIEW_SNAPSHOT_KEY]: {
    87					version: LOBU_VIEW_SNAPSHOT_VERSION,
    88					data: displaySafeSnapshotData(data),
    89				},
    90			},
    91		};
