it("restores view state when a standard capability follows cached widget data", async () => {
	const compatParent: CompatParent = Object.assign(new EventTarget(), {
		location: { origin: "https://chatgpt.com" },
	});
	Object.defineProperty(window, "parent", {
		configurable: true,
		value: compatParent,
	});
	Object.defineProperty(window, "openai", {
		configurable: true,
		value: { toolOutput: { title: "Cached widget result" } },
	});
	bridge.callServerTool.mockImplementation(async ({ name }) => ({
		isError: false,
		...(name === "restore_lobu_app_result"
			? {
					structuredContent: {
						found: true,
						tool_name: "query_sdk",
						data: { title: "Historical snapshot data" },
						view_state: { "details.open": true },
					},
				}
			: {}),
	}));

	const { Provider, useMcpApp } = await import("./host");
	function Probe() {
		const { data, viewState } = useMcpApp<{ title: string }>();
		return (
			<>
				<span>{data?.title}</span>
				<span>open:{String(viewState["details.open"])}</span>
			</>
		);
	}
	render(
		<Provider devMock={{ title: "Development result" }}>
			<Probe />
		</Provider>,
	);
	expect(await screen.findByText("Cached widget result")).toBeInTheDocument();
	await waitFor(() => expect(bridge.connect).toHaveBeenCalledTimes(1));

	act(() => {
		for (const handler of bridge.listeners.get("toolresult") ?? []) {
			handler({
				structuredContent: {},
				_meta: {
					"lobu/mcp-app-snapshot-capability": "cached-widget-token",
				},
			});
		}
	});

	expect(await screen.findByText("open:true")).toBeInTheDocument();
	expect(screen.getByText("Cached widget result")).toBeInTheDocument();
	expect(screen.queryByText("Historical snapshot data")).not.toBeInTheDocument();
	expect(bridge.callServerTool).toHaveBeenCalledWith({
		name: "restore_lobu_app_result",
		arguments: { snapshot_capability: "cached-widget-token" },
	});
});

it("replaces stale widget data with a capability-restored card", async () => {
	Object.defineProperty(window, "openai", {
		configurable: true,
		value: {
			widgetState: {
				privateContent: {
					lobuViewSnapshot: {
						version: 1,
						data: { title: "Old cached card" },
					},
				},
			},
		},
	});
	const compatParent: CompatParent = Object.assign(new EventTarget(), {
		location: { origin: window.location.origin },
		openai: {
			toolResponseMetadata: {
				mcp_tool_result: {
					_meta: {
						"lobu/mcp-app-snapshot-capability": "new-card-token",
					},
				},
			},
		},
	});
	Object.defineProperty(window, "parent", {
		configurable: true,
		value: compatParent,
	});
	bridge.callServerTool.mockImplementation(async ({ name }) => ({
		isError: false,
		...(name === "restore_lobu_app_result"
			? {
					structuredContent: {
						found: true,
						tool_name: "query_sdk",
						data: { title: "Current restored card" },
						view_state: { "details.open": true },
					},
				}
			: {}),
	}));

	const { Provider, useMcpApp } = await import("./host");
	function Probe() {
		const { data, viewState } = useMcpApp<{ title: string }>();
		return (
			<>
				<span>{data?.title}</span>
				<span>open:{String(viewState["details.open"])}</span>
			</>
		);
	}
	render(
		<Provider devMock={{ title: "Development result" }}>
			<Probe />
		</Provider>,
	);

	expect(await screen.findByText("Current restored card")).toBeInTheDocument();
	expect(await screen.findByText("open:true")).toBeInTheDocument();
	expect(screen.queryByText("Old cached card")).not.toBeInTheDocument();
});

